Create two new classes:

```python
class CustomerDescriptionService:
    def __init__(self, width: int = 40):
        self._width = width

    def describe(self, customer) -> str:
        parts = [
            str(customer.customer_id()),
            customer.name(),
            customer.email(),
            customer.tier(),
        ]
        return " | ".join(parts).ljust(self._width)
```

```python
class MailSummaryService:
    def __init__(self, mailer: EmailClient, repository: OrderRepository):
        self._mailer = mailer
        self._repository = repository

    def send_summary(self, address: str) -> dict[str, str]:
        return self._mailer.send(address, f"{self._repository.count()} orders")
```

Refactor `ReportView` to delegate:

```python
class ReportView:
    def __init__(self, repository: OrderRepository, mailer: EmailClient) -> None:
        self._repository = repository
        self._mailer = mailer
        self._width = 40
        self._customer_desc = CustomerDescriptionService(self._width)
        self._mail_summary = MailSummaryService(mailer, repository)

    def title(self) -> str:
        return "Orders".center(self._width, "-")

    def describe_customer(self, customer) -> str:
        return self._customer_desc.describe(customer)

    def order_count(self) -> int:
        return self._repository.count()

    def mail_summary(self, address: str) -> dict[str, str]:
        return self._mail_summary.send_summary(address)
```

Now `ReportView` only deals with formatting and repository queries, while the new services handle domain-specific logic and external communication.

